{"id": "reframe-001", "category": "Creative Growth", "subcategory": "Cognitive Reframing", "content_type": "situation_based", "title": "Separating Self from Work", "affirmation": "My worth is not defined by this draft. Feedback helps me refine the work, not judge my identity.", "situation": "Receiving critical feedback on a creative project that feels deeply personal.", "tone": "gentle", "purpose": "To decouple personal identity from professional or creative output.", "duration_minutes": 5, "practice_steps": ["Pause and take three deep breaths before reading the feedback.", "Identify specific actionable points rather than general feelings of inadequacy.", "List three things you like about yourself unrelated to this project."], "reflection_questions": ["Where do I feel this criticism in my body?", "What evidence exists that I am talented outside this specific project?"], "journaling_prompt": "Write about a time you improved something without losing your sense of worth.", "closing_message": "You are more than any single project.", "tags": ["self-worth", "feedback", "identity"]}
