{"id": "burnout_recovery_day2", "category": "Mental Health", "subcategory": "Social Burnout", "content_type": "situation_based", "title": "Navigating Social Invitations", "affirmation": "Choosing solitude over obligation is an act of self-care, not selfishness.", "situation": "You receive an invitation to a social event when you are feeling exhausted.", "tone": "realistic", "purpose": "To practice setting boundaries in low-stakes scenarios.", "duration_minutes": 15, "practice_steps": ["Pause before responding to check your energy levels.", "Draft a polite 'no' or 'not right now' response.", "Read the response aloud to build confidence."], "reflection_questions": ["What fear arises when you consider saying no?", "What is one gentle way to communicate your limits?"], "journaling_prompt": "Draft a response to an invitation that honors your current energy levels.", "closing_message": "Your boundaries protect your peace and allow you to show up authentically later.", "tags": ["boundaries", "communication", "social-pressure", "limits"]}
{"id": "burnout_recovery_day3", "category": "Mental Health", "subcategory": "Social Burnout", "content_type": "affirmation", "title": "Honoring Your Need for Space", "affirmation": "My need for solitude is valid and essential for my well-being and growth.", "situation": null, "tone": "empowering", "purpose": "To reinforce the long-term value of solitude in personal health.", "duration_minutes": 5, "practice_steps": [], "reflection_questions": ["What signs tell me I am reaching my limit?", "What helps you feel recharged after being alone?"], "journaling_prompt": "List three activities you enjoy doing solely for yourself without social pressure.", "closing_message": "You are allowed to prioritize your internal world without guilt.", "tags": ["solitude", "identity", "growth", "empowerment"]}

{"id": "cr_001", "category": "Career Resilience", "subcategory": "Initial Impact", "content_type": "situation_based", "title": "Processing the Initial Shock", "affirmation": null, "situation": "Feeling a sense of failure after a rejected application, missed promotion, or project that did not go as planned.", "tone": "grounding", "purpose": "To validate current emotions while separating professional outcomes from personal value.", "duration_minutes": 15, "practice_steps": ["Sit in a quiet space and breathe for 60 seconds.", "Notice where the feeling of disappointment sits in your body.", "Label the emotion objectively, such as 'I am experiencing frustration,' without judging the feeling.", "Ask yourself what this emotion needs right now without trying to fix it."], "reflection_questions": ["What specific part of this situation feels the most painful right now?", "What story am I telling myself about what this means?", "How much of my current distress is based on my own standards versus perceived external expectations?"], "journaling_prompt": "Describe the setback as if it happened to a respected colleague. What empathy would you offer them, and why is it difficult to offer that same empathy to yourself?", "closing_message": "It is okay to feel this. Acknowledging the pain is the first step toward processing it.", "tags": ["emotional acceptance", "career", "grounding"]}
{"id": "cr_002", "category": "Career Resilience", "subcategory": "Cognitive Reframing", "content_type": "practice", "title": "The Data Extraction Method", "affirmation": null, "situation": "You are ready to analyze the setback objectively.", "tone": "realistic", "purpose": "To shift the narrative from a personal failure to a collection of objective data points.", "duration_minutes": 20, "practice_steps": ["Write down the exact outcome without using subjective adjectives.", "Identify which variables were within your control and which were external factors.", "Identify one specific piece of information this outcome provides about your current process.", "Draft a revised approach based on this new information."], "reflection_questions": ["If you remove the word 'failure' from this event, what objective facts remain?", "What is the difference between a failed attempt and a failed person?", "How can you treat this as information rather than a verdict?"], "journaling_prompt": "Write down three 'data points' from this experience that will make your next attempt more informed and strategic.", "closing_message": "You are the scientist gathering information for your next move, not the experiment.", "tags": ["CBT", "reframing", "growth-mindset"]}
{"id": "cr_003", "category": "Career Resilience", "subcategory": "Self-Worth", "content_type": "affirmation", "title": "Decoupling Worth from Work", "affirmation": "My value as a person is independent of my professional achievements or the outcomes of my work.", "situation": null, "tone": "gentle", "purpose": "To reinforce internal stability and intrinsic worth separate from professional achievements.", "duration_minutes": 5, "practice_steps": [], "reflection_questions": ["What parts of my identity exist entirely outside of my job title?", "Who am I when I am not producing something for others?"], "journaling_prompt": "List five qualities you possess that have nothing to do with your career, your productivity, or your professional status.", "closing_message": "Repeat this when self-doubt arises. You are a whole person, regardless of your professional trajectory.", "tags": ["self-worth", "identity", "compassion"]}

{"id": "cb-001", "category": "Emotional Regulation", "subcategory": "Self-Worth", "content_type": "affirmation", "title": "Intrinsic Value Reminder", "affirmation": "My worth is defined by my character and kindness, not by what I own.", "situation": null, "tone": "grounding", "purpose": "To shift focus from external validation to internal self-worth.", "duration_minutes": null, "practice_steps": [], "reflection_questions": [], "journaling_prompt": "What are three qualities I possess that have nothing to do with money or possessions?", "closing_message": "Remember that your essence is far more valuable than any object.", "tags": ["self-worth", "materialism", "mindset"]}
{"id": "cb-002", "category": "Consumer Behavior", "subcategory": "Impulse Control", "content_type": "practice", "title": "The 24-Hour Purchase Pause", "affirmation": "I have the power to decide if this purchase truly adds value to my life.", "situation": null, "tone": "realistic", "purpose": "To break the cycle of impulsive consumption driven by emotional voids.", "duration_minutes": 1440, "practice_steps": ["Identify the item you want to buy and the emotion driving the urge.", "Close the browser tab or leave the store.", "Wait 24 hours before revisiting the purchase.", "Ask if this solves a problem or fills an emotional gap."], "reflection_questions": ["What emotion was I trying to soothe with this purchase?", "Will I still value this item in a month?"], "journaling_prompt": "Describe how you felt before and after the waiting period.", "closing_message": "Giving yourself space helps clarify true needs versus wants.", "tags": ["impulse-control", "financial-wellness", "mindfulness"]}
{"id": "cb-003", "category": "Emotional Regulation", "subcategory": "Social Comparison", "content_type": "situation_based", "title": "Navigating Social Media Envy", "affirmation": "I can appreciate others' success without feeling that I am lacking.", "situation": "Scrolling through feeds filled with luxury items and feeling inadequate.", "tone": "gentle", "purpose": "To manage feelings of inadequacy and validation needs triggered by online content.", "duration_minutes": 10, "practice_steps": ["Pause scrolling and acknowledge the feeling of envy without judgment.", "Take three deep breaths to ground yourself.", "Remind yourself that online posts are highlights, not a complete reality.", "Shift focus to a genuine connection or your own current values."], "reflection_questions": ["What specific need am I trying to meet through comparison?", "How can I validate myself in this moment?"], "journaling_prompt": "Write down three non-material things you are grateful for today.", "closing_message": "Your journey is unique and valuable without comparison.", "tags": ["social-media", "comparison", "validation"]}

{"id": "gy-practice-01", "category": "Life Transitions", "subcategory": "Gap Year Planning", "content_type": "practice", "title": "Balanced Gap Year Roadmap", "affirmation": "My growth happens in waves, not straight lines, and that is perfectly okay.", "situation": null, "tone": "grounding", "purpose": "Structure your gap year with flexibility for adventure, rest, and skill development.", "duration_minutes": 45, "practice_steps": ["List three core values you want to embody during this year.", "Identify one hard skill and one soft skill to develop.", "Create a flexible monthly roadmap allocating time for structured learning and unplanned adventure.", "Schedule monthly reviews to evaluate if activities align with your values and adjust without self-judgment."], "reflection_questions": ["What does success look like beyond productivity?", "How will I handle moments of uncertainty?"], "journaling_prompt": "Describe a perfect week during your gap year that balances doing and being.", "closing_message": "Remember, this plan serves you, not the other way around.", "tags": ["gap year", "planning", "balance", "growth"]}
{"id": "gy-affirm-01", "category": "Self-Validation", "subcategory": "Non-Linear Growth", "content_type": "affirmation", "title": "Validating the Non-Linear Path", "affirmation": "I trust my own timing and honor the detours that teach me resilience.", "situation": null, "tone": "gentle", "purpose": "Reduce pressure to follow a traditional timeline and validate your unique journey.", "duration_minutes": 5, "practice_steps": [], "reflection_questions": ["Where do I feel pressure to rush?", "What have I learned from past detours?"], "journaling_prompt": "Write about a time a detour led to unexpected growth.", "closing_message": "Your path is uniquely yours to walk.", "tags": ["affirmation", "self-trust", "patience"]}
{"id": "gy-sit-01", "category": "Emotional Regulation", "subcategory": "Transition Anxiety", "content_type": "situation_based", "title": "Navigating Uncertainty During Transition", "affirmation": "It is safe to pause and figure things out as I go.", "situation": "Feeling overwhelmed by peers moving forward while you explore during your gap year.", "tone": "realistic", "purpose": "Normalize feelings of being behind and balance exploration with intentional skill acquisition.", "duration_minutes": 15, "practice_steps": ["Acknowledge the feeling without judging it.", "Remind yourself that comparison steals joy.", "Focus on one small step forward today."], "reflection_questions": ["What am I afraid of missing out on?", "What am I gaining by taking this time?"], "journaling_prompt": "List three benefits of taking your own path instead of the expected one.", "closing_message": "You are not behind; you are on your own timeline.", "tags": ["anxiety", "comparison", "transition"]}

{"id":"seq-gray-001","category":"Mindset","subcategory":"Academic Balance","content_type":"affirmation","title":"Embracing the Middle Ground","affirmation":"My academic value is not defined by a perfect score, and real progress exists in the spaces between extremes.","situation":null,"tone":"gentle","purpose":"To soften rigid thinking patterns about success and provide a calming mantra.","duration_minutes":2,"practice_steps":[],"reflection_questions":[],"journaling_prompt":null,"closing_message":"Take a breath and let this truth settle.","tags":["self-worth","affirmation","academic-pressure"]}
{"id":"seq-gray-002","category":"Mindset","subcategory":"Cognitive Reframing","content_type":"practice","title":"Mapping the Academic Spectrum","affirmation":null,"situation":null,"tone":"grounding","purpose":"To visually and mentally map the spectrum between total failure and total perfection.","duration_minutes":15,"practice_steps":["Draw a line on a page from 0% (Total Failure) to 100% (Absolute Perfection).","Mark where your current academic situation actually sits.","Identify the qualities of the 40-70% range, the 'middle gray' where most learning happens.","List three things you learned during the process regardless of the result."],"reflection_questions":["How does it feel to see the space between the extremes?","What happens to your stress level when you aim for 'good enough' instead of 'perfect'?"],"journaling_prompt":"If you allowed yourself to be 'average' in one specific area of your studies, what would that free up mentally or emotionally for you?","closing_message":"Growth often happens in the gray area, not at the extremes.","tags":["mindset-shift","practical-exercise","academic-balance"]}
{"id":"seq-gray-003","category":"Mindset","subcategory":"Academic Performance","content_type":"situation_based","title":"Navigating Disappointing Feedback","affirmation":null,"situation":"You receive a grade lower than expected on a major assignment, feeling like a failure despite putting in significant effort.","tone":"realistic","purpose":"To navigate disappointment without collapsing into all-or-nothing thoughts.","duration_minutes":15,"practice_steps":["Acknowledge the disappointment without judgment.","Identify one specific factor within your control for next time.","Rate your effort on a scale of 1-10 separate from the outcome."],"reflection_questions":["Is there evidence that this outcome defines your entire capability?","What does this result actually mean for your long-term goals?","Are you treating yourself differently than you would a supportive friend?"],"journaling_prompt":"Write a letter to yourself about this grade from the perspective of a supportive mentor.","closing_message":"Your value persists regardless of where you fall on the grading curve. One result does not erase your capability or potential.","tags":["coping","academics","resilience","self-compassion"]}

