{"id": "perf_reframe_03", "category": "Personal Development", "subcategory": "Perfectionism", "content_type": "situation_based", "title": "Reframing Feedback Reception", "affirmation": "Feedback is data for growth, not a judgment on my entire identity or potential.", "situation": "Receiving critique. Thought: 'My supervisor suggested changes, so my work wasn't good enough and I disappointed them.'", "tone": "empowering", "purpose": "Separate personal worth from professional critique and reduce defensiveness.", "duration_minutes": 5, "practice_steps": ["Listen to the feedback objectively without interrupting.", "Ask clarifying questions to understand the suggestions.", "Implement the changes as a learning step."], "reflection_questions": ["Does this feedback target my character or the specific task?", "What is one actionable takeaway from this feedback?"], "journaling_prompt": "Describe a piece of criticism you received that ultimately helped you improve a skill.", "closing_message": "Your value exists independently of any single project's outcome. Growth happens in the editing process.", "tags": ["feedback", "resilience", "professional growth"]}
