{"id": "resilience-001", "category": "Mental Health & Wellness", "subcategory": "Trauma-Informed Care", "content_type": "practice", "title": "Creative Grounding Routine", "affirmation": "I honor my pace. My feelings are valid. I am safe to create space for healing today.", "situation": null, "tone": "grounding", "purpose": "To integrate mindfulness and expressive arts for emotional regulation and safe processing.", "duration_minutes": 25, "practice_steps": ["Find a quiet space where you feel physically secure and gather simple materials.", "Spend five minutes breathing slowly, noticing physical sensations without judgment.", "Choose a color that represents any tension you feel, and begin to draw or paint freely.", "Focus on the physical movement of the art materials rather than the visual outcome.", "Acknowledge what emerged without analyzing it, then gently close the session."], "reflection_questions": ["What sensation felt safest during this practice?", "Did creating feel accessible enough for you today?"], "journaling_prompt": "If your creation had a voice, what would it say about how you feel right now?", "closing_message": "You are building resilience step by step. Rest whenever you need to.", "tags": ["trauma-informed", "mindfulness", "art therapy", "veterans", "healing"]}
