{"id": "reframe_001", "category": "Mindset", "subcategory": "Creative Confidence", "content_type": "situation_based", "title": "Growth Over Genius", "affirmation": "My abilities grow with consistent practice, not innate talent alone.", "situation": "Feeling like a fraud because others seem naturally gifted in their craft.", "tone": "realistic", "purpose": "Shift focus from innate ability to measurable progress.", "duration_minutes": 5, "practice_steps": ["Identify one specific skill you have improved over the last six months.", "Acknowledge the hours of work that led to that improvement."], "reflection_questions": ["What evidence do I have that I have improved through effort?"], "journaling_prompt": "Describe a time you struggled but improved through repetition.", "closing_message": "Your effort matters more than innate gift.", "tags": ["imposter syndrome", "growth mindset", "creativity"]}
{"id": "reframe_002", "category": "Mindset", "subcategory": "Creative Confidence", "content_type": "situation_based", "title": "The Power of Iteration", "affirmation": "Every expert was once a beginner willing to learn through mistakes.", "situation": "Comparing your early-stage work to someone else's finished, polished portfolio.", "tone": "empowering", "purpose": "Normalize the messy process of creation and reduce fear of errors.", "duration_minutes": 5, "practice_steps": ["Look at an old piece of work from your beginning.", "Compare it to your current work to see the progression."], "reflection_questions": ["Why is it unfair to compare my process to someone else's highlight reel?"], "journaling_prompt": "Describe a mistake that helped you grow.", "closing_message": "Persistence is the engine of creative mastery.", "tags": ["comparison", "persistence", "creative process"]}
