{"id": "sens_002", "category": "Boundaries", "subcategory": "Peer Dynamics", "content_type": "situation_based", "title": "Navigating Peer Judgment", "affirmation": null, "situation": "A peer tells you that you are 'too sensitive' after you express a feeling.", "tone": "realistic", "purpose": "Provide a way to handle external criticism of sensitivity", "duration_minutes": 5, "practice_steps": ["Take a deep breath to center yourself.", "Acknowledge your feeling without judgment.", "State calmly: 'I process things deeply, and that's how I experience the world.'", "Observe the other person's reaction without feeling the need to change yourself."], "reflection_questions": ["Does their definition of 'too sensitive' align with my own values?", "Who in my life values my empathy?"], "journaling_prompt": "Write about a time when being sensitive allowed you to notice something others missed.", "closing_message": "You deserve spaces that honor your depth.", "tags": ["boundaries", "communication", "peers"]}
